mapper.select:
SELECT pk_id, id, dict_type, parent_code, dict_code, dict_code_desc, content, sort_order, tenant_id,
       is_deleted, gmt_created, gmt_modified, gmt_deleted
FROM sys_dict
WHERE tenant_id = #{tenantId}
  AND dict_type = #{dictType}
  AND parent_code = #{parentCode}
  AND is_deleted = 0
ORDER BY sort_order DESC, dict_code

